<main class="admin-shell"><?= view('partials/admin_sidebar',['active'=>'attendance']) ?><section class="admin-content"><div class="admin-topbar"><div><span class="eyebrow accent">ENTRY OPERATIONS</span><h1 data-testid="attendance-page-title">Live attendance</h1></div><a class="button button-yellow" href="<?= base_url('scanner') ?>" data-testid="open-scanner-button">Open scanner ↗</a></div><div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">ALL SCAN DECISIONS</span><h2 data-testid="scan-attempt-count"><?= count($entries) ?> attempts logged</h2></div><a class="text-link" href="<?= base_url('admin/reports') ?>">Reports ↗</a></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Time</th><th>Participant</th><th>Event / day</th><th>Gate / scanner</th><th>Decision</th><th>Reason</th></tr></thead><tbody><?php foreach($entries as $entry): ?><tr data-testid="attendance-table-row"><td class="mono"><?= esc(date('d M H:i:s',strtotime($entry['attempted_at']))) ?></td><td><strong><?= esc($entry['participant_name']?:'Unknown token') ?></strong><span class="table-sub"><?= esc($entry['registration_id']?:('••••'.$entry['token_hint'])) ?></span></td><td><?= esc($entry['event_name']?:'—') ?><span class="table-sub"><?= esc($entry['day_label']?:'—') ?></span></td><td><?= esc($entry['gate_name']?:'—') ?><span class="table-sub"><?= esc($entry['scanner_name']?:'—') ?></span></td><td><span class="<?= status_class($entry['status']) ?>"><?= esc(strtoupper($entry['status'])) ?></span></td><td><?= esc($entry['reason']) ?></td></tr><?php endforeach ?></tbody></table></div></div></section></main>